head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > isNumber]<br/>전달된 값의 타입이 Number 인지 판별하여 결과를 반환합니다.",
    "validation" : [
        "value(필수) 파라미터로 타입을 검사할 값을 설정할 수 있어야 합니다.",
        "value 파라미터의 타입이 Number 이면 true 를 반환해야 합니다.",
        "value 파라미터의 타입이 Number 가 아니면 false 를 반환해야 합니다.",
        "value 파라미터가 null 또는 undefined 이면 false 를 반환해야 합니다.",
        "문자열로 된 숫자(예: '12')는 Number 타입이 아니므로 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_isNumber_number_onclick = function () {
    let ret = WebSquare.util.isNumber(12);
    wf_body_bottom.getObj("scwin").setReturnValue("isNumber(12) : " + ret);
}

scwin.btn_isNumber_string_onclick = function () {
    let ret = WebSquare.util.isNumber("12");
    wf_body_bottom.getObj("scwin").setReturnValue("isNumber('12') : " + ret);
}

scwin.btn_isNumber_null_onclick = function () {
    let ret = WebSquare.util.isNumber(null);
    wf_body_bottom.getObj("scwin").setReturnValue("isNumber(null) : " + ret);
}

scwin.btn_isNumber_undefined_onclick = function () {
    let ret = WebSquare.util.isNumber(undefined);
    wf_body_bottom.getObj("scwin").setReturnValue("isNumber(undefined) : " + ret);
}

scwin.btn_isNumber_float_onclick = function () {
    let ret = WebSquare.util.isNumber(3.14);
    wf_body_bottom.getObj("scwin").setReturnValue("isNumber(3.14) : " + ret);
}
